package com.example.proyectolp.service;
public final class LevelCurve {private LevelCurve(){}public static int threshold(int level){if(level<=1)return 0;long value=50L*level*(level-1);return value>=Integer.MAX_VALUE?Integer.MAX_VALUE:(int)value;}public static int level(int xp){int n=1;while(threshold(n+1)<Integer.MAX_VALUE&&threshold(n+1)<=xp)n++;return n;}public static String rank(int level){if(level<5)return "Novato";if(level<10)return "Aprendiz";if(level<20)return "Constante";if(level<35)return "Experto";return "Maestro";}public static double progress(int xp){int l=level(xp),start=threshold(l),end=threshold(l+1);return end==start?0:(double)(xp-start)/(end-start);}public static int xpToNext(int xp){int l=level(xp);return threshold(l+1)-xp;}}
